    [Xunit.Fact]
    public static void TestHealthScores() {
        emon.Testport.AssertEq(Tlhealth.ThScore(1000, 0, 0, 0), 1000, "a perfect font");
        emon.Testport.AssertEq(Tlhealth.ThScore(1000, 0, 500, 500), 1000, "the limits are free");
        emon.Testport.AssertThat(Tlhealth.ThScore(1000, 0, 100, 0) >= Tlhealth.ThTrusted(), "a normal font is trusted");
        emon.Testport.AssertThat(Tlhealth.ThScore(0, 1000, 0, 0) < 300, "an unmapped font is far under 300");
        emon.Testport.AssertThat(Tlhealth.ThScore(500, 0, 0, 0) < Tlhealth.ThTrusted(), "half unmapped is not trusted");
        emon.Testport.AssertThat(Tlhealth.ThScore(1000, 0, 1000, 0) < Tlhealth.ThAutoHealth(), "every glyph on its neighbour is not healthy");
        emon.Testport.AssertThat(Tlhealth.ThScore(1000, 0, 0, 3000) < Tlhealth.ThAutoHealth(), "words torn apart are not healthy");
        emon.Testport.AssertThat(Tlhealth.ThScore(1000, 500, 0, 0) < Tlhealth.ThTrusted(), "half garbage is not trusted");
        emon.Testport.AssertThat(Tlhealth.ThScore(800, 0, 0, 0) > Tlhealth.ThScore(600, 0, 0, 0), "more mapped, better");
    }
    internal static int TtHealth(byte[] file, int which) {
        // Run a document to its health rows; answer, for which 0 the rows, 1 how many are at least `tl-trusted`, 2 the lowest score,
        // 3 the highest score of the rows that are not at least `tl-trusted`.
        emon.Port.Cells ar = emon.Port.NewCells();
        emon.Port.Cells dc = emon.Port.NewCells();
        emon.Port.Cells a = emon.Port.NewCells();
        emon.Port.Cells b = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        emon.Port.Cells cx = emon.Port.NewCells();
        emon.Port.Cells ox = emon.Port.NewCells();
        emon.Port.Cells cs = emon.Port.NewCells();
        emon.Port.Cells @out = emon.Port.NewCells();
        emon.Port.Cells f0 = emon.Port.NewCells();
        emon.Port.Cells f1 = emon.Port.NewCells();
        emon.Port.Cells f2 = emon.Port.NewCells();
        emon.Port.Cells f3 = emon.Port.NewCells();
        emon.Port.Cells gl = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells mk = emon.Port.NewCells();
        emon.Port.Cells fnt = emon.Port.NewCells();
        emon.Port.Cells pg = emon.Port.NewCells();
        emon.Port.Cells wd = emon.Port.NewCells();
        emon.Port.Cells ln = emon.Port.NewCells();
        emon.Port.Cells pa = emon.Port.NewCells();
        emon.Port.Cells im = emon.Port.NewCells();
        emon.Port.Cells pts = emon.Port.NewCells();
        emon.Port.Cells gx = emon.Port.NewCells();
        emon.Port.Cells epages = emon.Port.NewCells();
        emon.Port.Cells feats = emon.Port.NewCells();
        emon.Port.Cells fw = emon.Port.NewCells();
        emon.Port.Cells fl = emon.Port.NewCells();
        emon.Port.Cells fa = emon.Port.NewCells();
        emon.Port.Cells hl = emon.Port.NewCells();
        emon.Port.Cells sc = emon.Port.NewCells();
        emon.Port.Src src = emon.Port.SrcOfBlob(file);
        int o = Pdfdoc.PdOpen(src, ar, dc, a, b, st);
        int i = 0;
        int good = 0;
        int low = 100000;
        int high = 0;
        if (o != 0) {
            return -1;
        }
        Pdfcontent.PcDocument(src, ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx);
        Tlhealth.ThRun(pg, gl, et, mk, fnt, wd, ln, im, epages, feats, fw, fl, fa, hl, sc);
        while (i < Player.HlCount(hl)) {
            if (Player.HlGet(hl, i, Player.HlfScore()) >= Tlhealth.ThTrusted()) {
                good += 1;
            } else if (Player.HlGet(hl, i, Player.HlfScore()) > high) {
                high = Player.HlGet(hl, i, Player.HlfScore());
            }
            if (Player.HlGet(hl, i, Player.HlfScore()) < low) {
                low = Player.HlGet(hl, i, Player.HlfScore());
            }
            i += 1;
        }
        if (which == 0) {
            return Player.HlCount(hl);
        }
        if (which == 1) {
            return good;
        }
        if (which == 2) {
            return low;
        }
        return high;
    }
    [Xunit.Fact]
    public static void TestAnUnmappedFontIsCaughtAndAShiftedOneIsNot() {
        // tl-broken-unmapped: one font whose glyphs have no Unicode (score far under 300); every other font of both pages is trusted
        emon.Testport.AssertEq(TtHealth(emon.Testport.TestFile("corpus/synth/pdf/tl-broken-unmapped.pdf"), 0), 7, "unmapped: rows");
        emon.Testport.AssertEq(TtHealth(emon.Testport.TestFile("corpus/synth/pdf/tl-broken-unmapped.pdf"), 1), 5, "unmapped: trusted rows");
        emon.Testport.AssertThat(TtHealth(emon.Testport.TestFile("corpus/synth/pdf/tl-broken-unmapped.pdf"), 2) < 300, "unmapped: the broken font is under 300");
        // tl-broken-shift: a plausible mapping that is wrong; the text layer cannot tell, OCR agreement can (P7.2)
        emon.Testport.AssertEq(TtHealth(emon.Testport.TestFile("corpus/synth/pdf/tl-broken-shift.pdf"), 0), TtHealth(emon.Testport.TestFile("corpus/synth/pdf/tl-broken-shift.pdf"), 1), "shifted: every font passes");
    }
